1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width,initial-scale=1">
6	<title>For Judges | FirstRun</title>
7	<meta name="description" content="Every FirstRun claim for the neatHack judges, with the file, trace or page that proves it. The agent, neatlogs, Entire, cfo.ai, the demo, the posts and the upstream PRs.">
8	<meta name="color-scheme" content="light">
9	<link rel="icon" href="../assets/logo.svg" type="image/svg+xml">
