131	.prs li{display:grid;grid-template-columns:250px minmax(0,1fr);gap:6px 24px;padding:16px 4px;border-bottom:1px solid var(--edge);align-items:baseline}
132	.prs li div{display:flex;flex-direction:column;gap:4px}
133	.prs .rp{font:500 13px var(--mono);color:var(--mut);display:flex;flex-direction:column;align-items:flex-start;gap:6px}
