147	/* what broke */
148	.broke{list-style:none;margin-top:clamp(32px,4vw,44px);display:flex;flex-direction:column;border-top:1px solid var(--edge)}
149	.broke li{display:grid;grid-template-columns:96px minmax(0,1fr);gap:4px 20px;padding:16px 4px;border-bottom:1px solid var(--edge);align-items:baseline}
150	.broke .num{font:600 clamp(20px,2.4vw,26px)/1.1 var(--mono);color:var(--c);letter-spacing:-.03em;text-align:right}
