160	.cp:hover{background:oklch(100% 0 0/.8)}
161	.code .note{padding:0 18px 16px}
162	
163	footer{max-width:1040px;margin:0 auto;padding:36px 24px 52px;display:flex;flex-direction:column;gap:14px;align-items:center;text-align:center;color:var(--mut);font-size:14.5px}
